import sys, json, datetime

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            req = json.loads(line)
        except Exception:
            continue
        mid = req.get("id")
        method = req.get("method", "")
        if method == "initialize":
            res = {"protocolVersion": "2024-11-05",
                   "capabilities": {"tools": {}},
                   "serverInfo": {"name": "clock", "version": "1.0.0"}}
        elif method == "notifications/initialized":
            continue
        elif method == "tools/list":
            res = {"tools": [{"name": "now", "description": "返回当前日期时间",
                              "inputSchema": {"type": "object", "properties": {}}}]}
        elif method == "tools/call":
            name = (req.get("params") or {}).get("name")
            if name != "now":
                res = {"content": [{"type": "text", "text": "unknown tool"}], "isError": True}
            else:
                t = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                res = {"content": [{"type": "text", "text": "instance-id: QX7M2 / current time: " + t}]}
        else:
            res = {}
        sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": mid, "result": res}, ensure_ascii=False) + "\n")
        sys.stdout.flush()

main()

